import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { execSync } from 'node:child_process';
import { createScenario, stepScenario, captureScenario, restoreScenario, scenarioCondition } from '../../src/core/scenarios';
import { SCENARIOS } from '../../src/scenarios/campaigns';
import { FACTIONS } from '../../src/core/content';
import { steerFinale, finaleCommands } from '../../scripts/scenarios/finale-strategy';
import type { ScenarioSession } from '../../src/core/scenario-types';
import type { UnitRole } from '../../src/core/types';

const paths=['src/core/scenarios.ts','src/core/scenario-types.ts','src/core/scenario-validation.ts','src/core/simulation.ts','src/core/content.ts','src/scenarios/campaigns.ts','scripts/scenarios/finale-strategy.ts'];
const sources=Object.fromEntries(paths.map(path=>[path,createHash('sha256').update(readFileSync(path)).digest('hex')]));
const provenance={base:execSync('git rev-parse HEAD',{encoding:'utf8'}).trim(),sources,fixedStepSeconds:.05,scope:'Only steerFinale, issueScenarioCommand, and stepScenario can change the running scenario. Evidence capture reads state.',runnerSource:readFileSync('work/finale-strategy/verify.ts','utf8')};
const own=(s:ScenarioSession)=>s.state.entities.filter(e=>e.side===0&&e.kind==='unit').map(e=>({id:e.id,role:e.role,x:e.x,y:e.y,hp:e.hp,maxHp:e.maxHp,shield:e.shield,maxShield:e.maxShield,momentum:e.momentum,illusion:e.illusion,raised:e.raised,order:structuredClone(e.order),entrenchedAt:e.entrenchedAt}));
const observable=(s:ScenarioSession)=>({units:own(s),corpses:s.state.corpses.map(c=>({...c}))});
mkdirSync('work/finale-strategy',{recursive:true});
for(const restored of [false,true])for(const definition of Object.values(SCENARIOS).filter(d=>d.boss)){
 let session=createScenario(definition),didRestore=false;
 const abilities:unknown[]=[], events:unknown[]=[], phases:unknown[]=[], responses:unknown[]=[], histories:unknown[]=[];
 let checkpoint:unknown=null;
 const consume=(before:ReturnType<typeof observable>,after:ReturnType<typeof observable>,newEvents:ScenarioSession['state']['events'])=>{
  for(const event of newEvents){events.push({time:session.state.time,...event});if(event.type==='ability'&&event.side===0){const caster=after.units.find(e=>e.id===event.source)??before.units.find(e=>e.id===event.source);abilities.push({time:session.state.time,event,ability:caster?FACTIONS[definition.faction].units[caster.role as UnitRole].ability:null,before,after});}}
 };
 while(session.runtime.outcome==='playing'&&session.state.time<301){
  let before=observable(session); const priorEvents=session.state.events.length;
  steerFinale(session);consume(before,observable(session),session.state.events.slice(priorEvents));
  before=observable(session); const warning=structuredClone(session.runtime.boss.telegraph),phase=session.runtime.boss.phase,interrupted=session.runtime.boss.interrupted,dodged=session.runtime.boss.dodged;
  stepScenario(session);consume(before,observable(session),session.state.events);
  if(phase!==session.runtime.boss.phase)phases.push({time:session.state.time,phase:session.runtime.boss.phase,entered:[...session.runtime.boss.phasesEntered],units:own(session)});
  if(interrupted!==session.runtime.boss.interrupted||dodged!==session.runtime.boss.dodged)responses.push({time:session.state.time,warning,interrupted:session.runtime.boss.interrupted,dodged:session.runtime.boss.dodged,units:own(session)});
  const w=session.runtime.boss.telegraph;
  if(restored&&!didRestore&&w&&w.resolveAt-session.state.time<.8){checkpoint={time:session.state.time,warning:structuredClone(w),units:own(session)};histories.push(...finaleCommands(session));session=restoreScenario(captureScenario(session));didRestore=true;}
 }
 histories.push(...finaleCommands(session));
 const commander=session.state.entities.find(e=>e.id===session.runtime.labels.commander);
 const checks={won:session.runtime.outcome==='won',allPhases:session.runtime.boss.phasesEntered.join(',')==='0,1,2',ability:abilities.length>0&&session.runtime.commandCounts.ability>0,response:session.runtime.boss.interrupted+session.runtime.boss.dodged>0,commanderAlive:!!commander&&commander.hp>0,objectiveSuccess:session.definition.objectives.every(o=>o.optional||scenarioCondition(session,o.success)),objectiveFailureAbsent:session.definition.objectives.every(o=>!o.failure||!scenarioCondition(session,o.failure)),restored:!restored||didRestore};
 const report={provenance,definition:definition.id,mode:restored?'warning-checkpoint':'fresh',outcome:session.runtime.outcome,time:session.state.time,checks,checkpoint,runtime:session.runtime,commander:commander?{id:commander.id,hp:commander.hp,maxHp:commander.maxHp}:null,commands:histories,events,abilities,phases,responses,final:captureScenario(session)};
 const attempt=restored?7:6;writeFileSync(`work/finale-strategy/${definition.id}-attempt${attempt}.json`,JSON.stringify(report,null,2));
 console.log(definition.id,report.mode,report.outcome,report.time.toFixed(2),JSON.stringify(checks));
 if(Object.values(checks).some(ok=>!ok))process.exitCode=1;
}
